export const researchSource={name:'博物馆历史评论研究集',url:'https://doi.org/10.6084/m9.figshare.21677282',author:'Juan Manuel Cano Sanchiz',published:'2022-12-06',license:'CC BY 4.0',retrieved:'2026-10-25'};
export function safeUrl(value){try{const u=new URL(value);return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
export function dedupe(incoming,existing=[]){const keys=new Set(existing.map(p=>p.text.trim().replace(/\s+/g,' ').toLowerCase())),ids=new Set(existing.map(p=>p.id));let duplicates=0;const items=[];for(const p of incoming){const key=p.text.trim().replace(/\s+/g,' ').toLowerCase();if(!key||keys.has(key)||ids.has(p.id)){duplicates++;continue;}keys.add(key);ids.add(p.id);items.push(p);}return {items,duplicates};}
export async function fetchPublicComments({query='museum',days=0,page=0,fetchImpl=globalThis.fetch}={}){
 if(!query.trim())throw Error('请填写检索关键词；建议 museum、science museum、children museum。');
 const url=new URL('https://hn.algolia.com/api/v1/search_by_date');url.searchParams.set('query',query.trim());url.searchParams.set('tags','comment');url.searchParams.set('hitsPerPage','50');url.searchParams.set('page',String(page));if(days)url.searchParams.set('numericFilters','created_at_i>'+Math.floor(Date.now()/1000-days*86400));
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);
 try{const res=await fetchImpl(url,{signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!res.ok)throw Error('公开搜索服务返回 HTTP '+res.status);const data=await res.json();if(!Array.isArray(data.hits))throw Error('接口响应不含有效评论列表');
 const strip=html=>{const d=new DOMParser().parseFromString(html||'','text/html');return d.body.textContent?.replace(/\s+/g,' ').trim()||'';};
 const items=data.hits.filter(h=>h.comment_text&&!/\b(hiring|who wants to be hired|freelancer)\b/i.test(h.story_title||'')).map(h=>({id:'HN-'+h.objectID,text:strip(h.comment_text),platform:'Hacker News',source:'HN Search · 公开讨论',sourceUrl:'https://news.ycombinator.com/item?id='+encodeURIComponent(h.objectID),evidenceUrl:'https://news.ycombinator.com/item?id='+encodeURIComponent(h.objectID),date:h.created_at?.slice(0,10)||'',publishedAt:h.created_at||'',collectedAt:new Date().toISOString(),kind:'public-discussion',language:'en',threadTitle:h.story_title||'',provenance:'通过 HN Search (Algolia) 公开评论接口读取；移除 HTML，不保留作者字段；未生成或翻译评论',license:'原作者内容；按原平台条款使用',analyzed:true})).filter(p=>p.text.length>=8);
 return {...dedupe(items),query:query.trim(),fetchedAt:new Date().toISOString(),requestUrl:url.href,page,pages:data.nbPages||0,total:data.nbHits||0,received:data.hits.length,excluded:data.hits.length-items.length};
 }catch(e){if(e.name==='AbortError')throw Error('公开检索超时，请稍后重试。不会使用模拟评论替代。');throw e;}finally{clearTimeout(timer);}
}
